            ulong time_unix_nano;

            /// <summary>
            /// The number of values in the population. Must be
            /// non-negative. This value must be equal to the sum of the "bucket_counts"
            /// values in the positive and negative Buckets plus the "zero_count" field.
            /// </summary>
            ulong count;

            /// <summary>
            /// The sum of the values in the population. If count is zero then this field
            /// must be zero.
            ///
            /// Note: Sum should only be filled out when measuring non-negative discrete
            /// events, and is assumed to be monotonic over the values of these events.
            /// Negative events *can* be recorded, but sum should not be filled out when
            /// doing so.  This is specifically to enforce compatibility w/ OpenMetrics,
            /// see: https://github.com/prometheus/OpenMetrics/blob/v1.0.0/specification/OpenMetrics.md#histogram
            /// </summary>
            double? sum;

            /// <summary>
            /// scale describes the resolution of the histogram.  Boundaries are
            /// located at powers of the base, where:
            ///
            ///   base = (2^(2^-scale))
            ///
            /// The histogram bucket identified by `index`, a signed integer,
            /// contains values that are greater than (base^index) and
            /// less than or equal to (base^(index+1)).
            ///
            /// The positive and negative ranges of the histogram are expressed
            /// separately.  Negative values are mapped by their absolute value
            /// into the negative range using the same scale as the positive range.
            ///
            /// scale is not restricted by the protocol, as the permissible
            /// values depend on the range of the data.
            /// </summary>
            [X] int scale;

            /// <summary>
            /// The count of values that are either exactly zero or
            /// within the region considered zero by the instrumentation at the
            /// tolerated degree of precision.  This bucket stores values that
            /// cannot be expressed using the standard exponential formula as
            /// well as values that have been rounded to zero.
            ///
            /// Implementations MAY consider the zero bucket to have probability
            /// mass equal to (zero_count / count).
            /// </summary>
            ulong zero_count;

            /// <summary>positive carries the positive range of exponential bucket counts.</summary>
            Buckets positive;

            /// <summary>negative carries the negative range of exponential bucket counts.</summary>
            Buckets negative;

            /// <summary>
            /// Buckets are a set of bucket counts, encoded in a contiguous array
            /// of counts.
            /// </summary>
            public class Buckets {
                /// <summary>
                /// The bucket index of the first entry in the bucket_counts array.
                ///
                /// Note: This uses a varint encoding as a simple form of compression.
                /// </summary>
                [X] int offset;

                /// <summary>
                /// An array of count values, where bucket_counts[i] carries
                /// the count of the bucket at index (offset+i). bucket_counts[i] is the count
                /// of values greater than base^(offset+i) and less than or equal to
                /// base^(offset+i+1).
                ///
                /// Note: By contrast, the explicit HistogramDataPoint uses
                /// fixed64.  This field is expected to have many buckets,
                /// especially zeros, so uint64 has been selected to ensure
                /// varint encoding.
                /// </summary>
                [A] ulong[,,] bucket_counts;
            }

            /// <summary>
            /// Flags that apply to this specific data point.  See DataPointFlags
            /// for the available flags and their meaning.
            /// </summary>
            [A] uint flags;

            /// <summary>
            /// (Optional) List of exemplars collected from
            /// measurements that were used to form the data point
            /// </summary>
            Exemplar[,,] exemplars;

            /// <summary>The minimum value over (start_time, end_time].</summary>
            double? min;

            /// <summary>The maximum value over (start_time, end_time].</summary>
            double? max;

            /// <summary>
            /// ZeroThreshold may be optionally set to convey the width of the zero
            /// region. Where the zero region is defined as the closed interval
            /// [-ZeroThreshold, ZeroThreshold].
            /// When ZeroThreshold is 0, zero count bucket stores values that cannot be
            /// expressed using the standard exponential formula as well as values that
            /// have been rounded to zero.
            /// </summary>
            double zero_threshold;
        }

        /// <summary>
        /// SummaryDataPoint is a single data point in a timeseries that describes the
        /// time-varying values of a Summary metric. The count and sum fields represent
        /// cumulative values.
        /// </summary>
        public class SummaryDataPoint {
            // reserved 1

            /// <summary>
            /// The set of key/value pairs that uniquely identify the timeseries from
            /// where this point belongs. The list may be empty (may contain 0 elements).
            /// Attribute keys MUST be unique (it is not allowed to have more than one
            /// attribute with the same key).
            /// The behavior of software that receives duplicated keys can be unpredictable.
            /// </summary>
            opentelemetry.proto.common.v1.KeyValue[,,] attributes;

            /// <summary>
            /// StartTimeUnixNano is optional but strongly encouraged, see the
            /// the detailed comments above Metric.
            ///
            /// Value is UNIX Epoch time in nanoseconds since 00:00:00 UTC on 1 January
            /// 1970.
            /// </summary>
            ulong start_time_unix_nano;

            /// <summary>
            /// TimeUnixNano is required, see the detailed comments above Metric.
            ///
            /// Value is UNIX Epoch time in nanoseconds since 00:00:00 UTC on 1 January
            /// 1970.
            /// </summary>
            ulong time_unix_nano;

            /// <summary>count is the number of values in the population. Must be non-negative.</summary>
            ulong count;

            /// <summary>
            /// sum of the values in the population. If count is zero then this field
            /// must be zero.
            ///
            /// Note: Sum should only be filled out when measuring non-negative discrete
            /// events, and is assumed to be monotonic over the values of these events.
            /// Negative events *can* be recorded, but sum should not be filled out when
            /// doing so.  This is specifically to enforce compatibility w/ OpenMetrics,
            /// see: https://github.com/prometheus/OpenMetrics/blob/v1.0.0/specification/OpenMetrics.md#summary
            /// </summary>
            double sum;

            /// <summary>
            /// Represents the value at a given quantile of a distribution.
            ///
            /// To record Min and Max values following conventions are used:
            /// - The 1.0 quantile is equivalent to the maximum value observed.
            /// - The 0.0 quantile is equivalent to the minimum value observed.
            ///
            /// See the following issue for more context:
            /// https://github.com/open-telemetry/opentelemetry-proto/issues/125
            /// </summary>
            public class ValueAtQuantile {
                /// <summary>
                /// The quantile of a distribution. Must be in the interval
                /// [0.0, 1.0].
                /// </summary>
                double quantile;

                /// <summary>
                /// The value at the given quantile of a distribution.
                ///
                /// Quantile values must NOT be negative.
                /// </summary>
                double value;
            }

            /// <summary>
            /// (Optional) list of values at different quantiles of the distribution calculated
            /// from the current snapshot. The quantiles must be strictly increasing.
            /// </summary>
            ValueAtQuantile[,,] quantile_values;

            /// <summary>
            /// Flags that apply to this specific data point.  See DataPointFlags
            /// for the available flags and their meaning.
            /// </summary>
            [A] uint flags;
        }

        /// <summary>
        /// A representation of an exemplar, which is a sample input measurement.
        /// Exemplars also hold information about the environment when the measurement
        /// was recorded, for example the span and trace ID of the active span when the
        /// exemplar was recorded.
        /// </summary>
        public class Exemplar {
            // reserved 1

            /// <summary>
            /// The set of key/value pairs that were filtered out by the aggregator, but
            /// recorded alongside the original measurement. Only key/value pairs that were
            /// filtered out by the aggregator should be included
            /// </summary>
            opentelemetry.proto.common.v1.KeyValue[,,] filtered_attributes;

            /// <summary>
            /// time_unix_nano is the exact time when this exemplar was recorded
            ///
            /// Value is UNIX Epoch time in nanoseconds since 00:00:00 UTC on 1 January
            /// 1970.
            /// </summary>
            ulong time_unix_nano;

            /// <summary>
            /// The value of the measurement that was recorded. An exemplar is
            /// considered invalid when one of the recognized value fields is not present
            /// inside this oneof.
            /// A oneof in protobuf: one of the alternatives is set.
            /// </summary>
            public class Value {
                double? as_double;
                long? as_int;
            }

            Value value;

            /// <summary>
            /// (Optional) Span ID of the exemplar trace.
            /// span_id may be missing if the measurement is not recorded inside a trace
            /// or if the trace is not sampled.
            /// </summary>
            Binary[,,] span_id;

            /// <summary>
            /// (Optional) Trace ID of the exemplar trace.
            /// trace_id may be missing if the measurement is not recorded inside a trace
            /// or if the trace is not sampled.
            /// </summary>
            Binary[,,] trace_id;
        }

        public struct opentelemetry {
            public struct proto {
                public struct resource {
                    public struct v1 {
                        // from opentelemetry/opentelemetry/proto/resource/v1/resource.proto

                        /// <summary>Resource information.</summary>
                        public class Resource {
                            /// <summary>
                            /// Set of attributes that describe the resource.
                            /// Attribute keys MUST be unique (it is not allowed to have more than one
                            /// attribute with the same key).
                            /// The behavior of software that receives duplicated keys can be unpredictable.
                            /// </summary>
                            common.v1.KeyValue[,,] attributes;

                            /// <summary>
                            /// The number of dropped attributes. If the value is 0, then
                            /// no attributes were dropped.
                            /// </summary>
                            [A] uint dropped_attributes_count;

                            /// <summary>
                            /// Set of entities that participate in this Resource.
                            ///
                            /// Note: keys in the references MUST exist in attributes of this message.
                            ///
                            /// Status: [Development]
                            ///
                            /// [Since v1.6.0]
                            /// </summary>
                            common.v1.EntityRef[,,] entity_refs;
                        }
                    }
                }

                public struct common {
                    public struct v1 {
                        // from opentelemetry/opentelemetry/proto/common/v1/common.proto

                        /// <summary>
                        /// InstrumentationScope is a message representing the instrumentation scope information
                        /// such as the fully qualified name and version.
                        /// </summary>
                        public class InstrumentationScope {
                            /// <summary>
                            /// A name denoting the Instrumentation scope.
                            /// An empty instrumentation scope name means the name is unknown.
                            /// </summary>
                            string name;

                            /// <summary>
                            /// Defines the version of the instrumentation scope.
                            /// An empty instrumentation scope version means the version is unknown.
                            /// </summary>
                            string version;

                            /// <summary>
                            /// Additional attributes that describe the scope. [Optional].
                            /// Attribute keys MUST be unique (it is not allowed to have more than one
                            /// attribute with the same key).
                            /// The behavior of software that receives duplicated keys can be unpredictable.
                            /// </summary>
                            KeyValue[,,] attributes;

                            /// <summary>
                            /// The number of attributes that were discarded. Attributes
                            /// can be discarded because their keys are too long or because there are too many
                            /// attributes. If this value is 0, then no attributes were dropped.
                            /// </summary>
                            [A] uint dropped_attributes_count;
                        }

                        /// <summary>
                        /// Represents a key-value pair that is used to store Span attributes, Link
                        /// attributes, etc.
                        /// </summary>
                        public class KeyValue {
                            /// <summary>
                            /// The key name of the pair.
                            /// key_strindex MUST NOT be set if key is used.
                            /// </summary>
                            string key;

                            /// <summary>The value of the pair.</summary>
                            AnyValue value;

                            /// <summary>
                            /// Reference to the string key in ProfilesDictionary.string_table.
                            /// key MUST NOT be set if key_strindex is used.
                            ///
                            /// Note: This is currently used exclusively in the Profiling signal.
                            /// Implementers of OTLP receivers for signals other than Profiling should
                            /// treat the presence of this key as a non-fatal issue.
                            /// Log an error or warning indicating an unexpected field intended for the
                            /// Profiling signal and process the data as if this value were absent or
                            /// empty, ignoring its semantic content for the non-Profiling signal.
                            ///
                            /// Status: [Alpha]
                            ///
                            /// [Since v1.10.0]
                            /// </summary>
                            [X] int key_strindex;
                        }

                        /// <summary>
                        /// A reference to an Entity.
                        /// Entity represents an object of interest associated with produced telemetry: e.g spans, metrics, profiles, or
                        /// logs.
                        ///
                        /// Status: [Development]
                        ///
                        /// [Since v1.6.0]
                        /// </summary>
                        public class EntityRef {
                            /// <summary>
                            /// The Schema URL, if known. This is the identifier of the Schema that the entity data
                            /// is recorded in. To learn more about Schema URL see
                            /// https://opentelemetry.io/docs/specs/otel/schemas/#schema-url
                            ///
                            /// This schema_url applies to the data in this message and to the Resource attributes
                            /// referenced by id_keys and description_keys.
                            /// TODO: discuss if we are happy with this somewhat complicated definition of what
                            /// the schema_url applies to.
                            ///
                            /// This field obsoletes the schema_url field in ResourceMetrics/ResourceSpans/ResourceLogs.
                            /// </summary>
                            string schema_url;

                            /// <summary>
                            /// Defines the type of the entity. MUST not change during the lifetime of the entity.
                            /// For example: "service" or "host". This field is required and MUST not be empty
                            /// for valid entities.
                            /// </summary>
                            string Type;

                            /// <summary>
                            /// Attribute Keys that identify the entity.
                            /// MUST not change during the lifetime of the entity. The Id must contain at least one attribute.
                            /// These keys MUST exist in the containing {message}.attributes.
                            /// </summary>
                            string[,,] id_keys;

                            /// <summary>
                            /// Descriptive (non-identifying) attribute keys of the entity.
                            /// MAY change over the lifetime of the entity. MAY be empty.
                            /// These attribute keys are not part of entity's identity.
                            /// These keys MUST exist in the containing {message}.attributes.
                            /// </summary>
                            string[,,] description_keys;
                        }

                        /// <summary>
                        /// Represents any type of attribute value. AnyValue may contain a
                        /// primitive value such as a string or integer or it may contain an arbitrary nested
                        /// object containing arrays, key-value lists and primitives.
                        /// </summary>
                        public class AnyValue {
                            /// <summary>
                            /// The value is one of the listed fields. It is valid for all values to be unspecified
                            /// in which case this AnyValue is considered to be "empty".
                            /// A oneof in protobuf: one of the alternatives is set.
                            /// </summary>
                            public class Value {
                                string? string_value;
                                bool? bool_value;
                                [X] long? int_value;
                                double? double_value;
                                ArrayValue? array_value;
                                KeyValueList? kvlist_value;
                                Binary[,,]? bytes_value;

                                /// <summary>
                                /// Reference to the string value in ProfilesDictionary.string_table.
                                ///
                                /// Note: This is currently used exclusively in the Profiling signal.
                                /// Implementers of OTLP receivers for signals other than Profiling should
                                /// treat the presence of this value as a non-fatal issue.
                                /// Log an error or warning indicating an unexpected field intended for the
                                /// Profiling signal and process the data as if this value were absent or
                                /// empty, ignoring its semantic content for the non-Profiling signal.
                                ///
                                /// Status: [Alpha]
                                ///
                                /// [Since v1.10.0]
                                /// </summary>
                                [X] int? string_value_strindex;
                            }

                            Value value;
                        }

                        /// <summary>
                        /// ArrayValue is a list of AnyValue messages. We need ArrayValue as a message
                        /// since oneof in AnyValue does not allow repeated fields.
                        /// </summary>
                        public class ArrayValue {
                            /// <summary>Array of values. The array may be empty (contain 0 elements).</summary>
                            AnyValue[,,] values;
                        }

                        /// <summary>
                        /// KeyValueList is a list of KeyValue messages. We need KeyValueList as a message
                        /// since `oneof` in AnyValue does not allow repeated fields. Everywhere else where we need
                        /// a list of KeyValue messages (e.g. in Span) we use `repeated KeyValue` directly to
                        /// avoid unnecessary extra wrapping (which slows down the protocol). The 2 approaches
                        /// are semantically equivalent.
                        /// </summary>
                        public class KeyValueList {
                            /// <summary>
                            /// A collection of key/value pairs of key-value pairs. The list may be empty (may
                            /// contain 0 elements).
                            ///
                            /// The keys MUST be unique (it is not allowed to have more than one
                            /// value with the same key).
                            /// The behavior of software that receives duplicated keys can be unpredictable.
                            /// </summary>
                            KeyValue[,,] values;
                        }
                    }
                }
            }
        }

        // ═════════════════════════ topology ═════════════════════════

        /// <summary>One side of the exchange.</summary>
        ///<see cref = 'InTS'/>   implementation in TypeScript
        ///<see cref = 'InCS'/>   implementation in C#
        ///<see cref = 'InJAVA'/> implementation in JAVA
        ///<see cref = 'InCPP'/>  implementation in C++
        ///<see cref = 'InRS'/>   implementation in RUST
        ///<see cref = 'InGO'/>   implementation in GO
        struct Server : Host { }

        /// <summary>The other side of the exchange.</summary>
        ///<see cref = 'InTS'/>   implementation in TypeScript
        ///<see cref = 'InCS'/>   implementation in C#
        ///<see cref = 'InJAVA'/> implementation in JAVA
        ///<see cref = 'InCPP'/>  implementation in C++
        ///<see cref = 'InRS'/>   implementation in RUST
        ///<see cref = 'InGO'/>   implementation in GO
        struct Client : Host { }

        interface ClientServerConnection : Connects<Client, Server> {
            // The .proto declares messages and no service: each travels on its own, either way; the state never changes.
            [_____lr_____<MetricsData>]
            struct Exchange { }
        }
    }
}
